import type { HTMLAttributes } from "astro/types";

type Props = HTMLAttributes<"div"> & {
  defaultOpen?: boolean;
  disabled?: boolean;
  modal?: boolean;
  openOnHover?: boolean;
  closeDelay?: number;
};

const {
  defaultOpen = false,
  disabled = false,
  modal = false,
  openOnHover = false,
  closeDelay = 200,
  ...rest
} = Astro.props;
---

<div
  {...rest}
  data-sw-menu
  data-default-open={defaultOpen ? "true" : undefined}
  data-disabled={disabled ? "" : undefined}
  data-modal={modal ? "true" : "false"}
  data-open-on-hover={openOnHover ? "true" : undefined}
  data-close-delay={closeDelay}
  data-state={defaultOpen ? "open" : "closed"}
>
  <slot />
</div>

<script>
  import { createMenu } from "@starwind-ui/runtime/menu";
  import { registerAstroControllerLifecycle } from "../internal/controller-lifecycle";

  const menuInstances = new Set<ReturnType<typeof createMenu>>();

  import { getAstroInitCandidates as getInitCandidates } from "../internal/controller-lifecycle";

  const setupMenus = (event?: Event) => {
    getInitCandidates(event, "[data-sw-menu]").forEach((root) => {
      if (root.hasAttribute("data-sw-context-menu")) return;
      menuInstances.add(createMenu(root));
    });
  };

  const destroyMenus = () => {
    menuInstances.forEach((instance) => instance.destroy());
    menuInstances.clear();
  };

  registerAstroControllerLifecycle("MenuRoot", setupMenus, destroyMenus);
</script>

