 * Vendored by the Starwind CLI.
 * You own this file in your project.
 */
import type { HTMLAttributes } from "astro/types";

type Props = Omit<HTMLAttributes<"div">, "defaultValue"> & {
  autoComplete?: string;
  defaultOpen?: boolean;
  defaultValue?: string | null;
  disabled?: boolean;
  form?: string;
  highlightItemOnHover?: boolean;
  modal?: boolean;
  name?: string;
  readOnly?: boolean;
  required?: boolean;
};

const {
  autoComplete,
  defaultOpen = false,
  defaultValue,
  disabled = false,
  form,
  highlightItemOnHover = true,
  modal = true,
  name,
  readOnly = false,
  required = false,
  ...rest
} = Astro.props;
---

<div
  {...rest}
  data-sw-select
  data-autocomplete={autoComplete}
  data-default-open={defaultOpen ? "true" : undefined}
  data-default-value={defaultValue ?? undefined}
  data-disabled={disabled ? "" : undefined}
  data-form={form}
  data-highlight-item-on-hover={highlightItemOnHover ? "true" : "false"}
  data-modal={modal ? "true" : "false"}
  data-name={name}
  data-readonly={readOnly ? "" : undefined}
  data-required={required ? "" : undefined}
  data-state={defaultOpen ? "open" : "closed"}
>
  <input
    data-sw-select-input
    type={required ? undefined : "hidden"}
    style="position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0"
    autocomplete={autoComplete}
    form={form}
    name={name}
    value={defaultValue ?? ""}
    aria-hidden="true"
    tabindex="-1"
  />
  <slot />
</div>

<script>
  import { createSelect } from "@starwind-ui/runtime/select";
  import {
    registerAstroControllerLifecycle,
    trackAstroController,
  } from "../internal/controller-lifecycle";

  import { getAstroInitCandidates as getInitCandidates } from "../internal/controller-lifecycle";

  const setupSelects = (event?: Event) => {
    getInitCandidates(event, "[data-sw-select]").forEach((root) => {
      trackAstroController("SelectRoot", root, createSelect(root));
    });
  };

  registerAstroControllerLifecycle("SelectRoot", setupSelects);
</script>

