import type { SidebarPersistenceStorage } from "@starwind-ui/runtime/sidebar";
import type { HTMLAttributes } from "astro/types";

type AstroSidebarPersistenceStorage = Extract<
  SidebarPersistenceStorage,
  "cookie" | "localStorage" | false
>;

type Props = HTMLAttributes<"div"> & {
  defaultOpen?: boolean;
  defaultMobileOpen?: boolean;
  keyboardShortcut?: string;
  mobileQuery?: string;
  persistOpen?: boolean;
  persistenceKey?: string;
  persistenceStorage?: AstroSidebarPersistenceStorage;
  persistenceMaxAge?: number;
};

const {
  defaultOpen = true,
  defaultMobileOpen = false,
  keyboardShortcut = "b",
  mobileQuery = "(max-width: 767.98px)",
  persistOpen = false,
  persistenceKey,
  persistenceStorage,
  persistenceMaxAge = 604800,
  ...rest
} = Astro.props;

const initialState = defaultOpen ? "expanded" : "collapsed";
// Astro has no component context. Record this initial state for the Sidebar parts in this request.
const sidebarInitialStatesKey = Symbol.for("starwind-ui.sidebar.initial-states");
const requestLocals = Astro.locals as unknown as
  | Record<symbol, Set<string> | undefined>
  | undefined;
if (requestLocals) {
  const sidebarInitialStates = requestLocals[sidebarInitialStatesKey] ?? new Set<string>();
  sidebarInitialStates.add(initialState);
  requestLocals[sidebarInitialStatesKey] = sidebarInitialStates;
}

const providerAttributes = Object.fromEntries(
  Object.entries(rest).filter(
    ([name]) =>
      ![
        "data-sw-sidebar-provider",
        "data-state",
        "data-mobile-open",
        "data-keyboard-shortcut",
        "data-mobile-query",
        "data-persistence-max-age",
      ].includes(name),
  ),
);
---

<div
  {...providerAttributes}
  data-sw-sidebar-provider
  data-default-open={defaultOpen ? "true" : undefined}
  data-default-mobile-open={defaultMobileOpen ? "true" : undefined}
  data-state={initialState}
  data-mobile-open={defaultMobileOpen ? "true" : "false"}
  data-keyboard-shortcut={keyboardShortcut}
  data-mobile-query={mobileQuery}
  data-persist-open={persistOpen ? "true" : undefined}
  data-persistence-key={persistenceKey}
  data-persistence-storage={persistenceStorage === false ? "false" : persistenceStorage}
  data-persistence-max-age={persistenceMaxAge}
>
  <slot />
</div>

<script>
  import { createSidebarController } from "@starwind-ui/runtime/sidebar";
  import {
    registerAstroControllerLifecycle,
    trackAstroController,
  } from "../internal/controller-lifecycle";

  import { getAstroInitCandidates as getInitCandidates } from "../internal/controller-lifecycle";

  const setupSidebars = (event?: Event) => {
    getInitCandidates(event, "[data-sw-sidebar-provider]").forEach((provider) =>
      trackAstroController("SidebarProvider", provider, createSidebarController(provider)),
    );
  };

  registerAstroControllerLifecycle("SidebarProvider", setupSidebars);
</script>

