function composeAsChildEventHandlers(
  parentHandler: (...args: unknown[]) => unknown,
  childHandler: (...args: unknown[]) => unknown,
  eventOrder: NonNullable<AsChildMergeOptions["eventOrder"]>,
): (...args: unknown[]) => void {
